import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry, BoxGeometry, PointLight } = ctx.THREE;
  const root = new Group();
  const subject = new Group();
  const resources = [];
  const primitiveResults = [];
  const timelines = [];
  let disposed = false;

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropMaterial = new MeshBasicNodeMaterial({
    toneMapped: false
  });
  backdropMaterial.colorNode = mix(
    color(colors.surface),
    color(colors.ink),
    uv().y
  );
  backdropMaterial.side = ctx.THREE.DoubleSide;

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  shadowMaterial.side = ctx.THREE.DoubleSide;

  const contactShadow = new Mesh(
    new CircleGeometry(1.25, 64),
    shadowMaterial
  );
  contactShadow.position.set(0, -0.92, -0.22);
  contactShadow.scale.set(1.45, 0.34, 1);
  root.add(contactShadow);
  resources.push(contactShadow.geometry, contactShadow.material);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    toneMapped: false
  });
  accentMaterial.side = ctx.THREE.DoubleSide;

  const accentBar = new Mesh(
    new BoxGeometry(1.45, 0.025, 0.035),
    accentMaterial
  );
  accentBar.position.set(0, -1.2, 0.24);
  root.add(accentBar);
  resources.push(accentBar.geometry, accentBar.material);

  const rimLight = new PointLight(colors.accent, 0.78, 4.5, 2);
  rimLight.position.set(-1.9, 1.35, 1.8);
  root.add(rimLight);

  subject.position.set(0, -0.15, 0);
  subject.scale.setScalar(0.96);
  root.add(subject);

  const entrance = gsap.timeline();
  entrance
    .to(subject.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.48,
      ease: 'power3.out'
    })
    .to(subject.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    });
  timelines.push(entrance);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  if (ctx.fontAtlas && items.length) {
    for (const item of items) {
      const text = typeof item.text === 'string' ? item.text : '';
      if (!text) continue;
      const textObject = ctx.fontAtlas.createText(text, {
        fontSize: item.typography?.fontSize,
        color: item.role === 'accent' ? colors.accent : colors.paper,
        align: item.typography?.align ?? 'center',
        maxWidthPx: item.typography?.maxWidthPx,
        letterSpacingPx: item.typography?.letterSpacingPx
      });
      textObject.position.set(
        item.position?.x ?? 0,
        item.position?.y ?? 0,
        item.position?.z ?? 0.3
      );
      root.add(textObject);
    }
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params ?? {});
      if (result) primitiveResults.push(result);
    }
  }

  if (config.meshUrl && ctx.glbLoader?.loadGLB) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;
      subject.add(gltf.scene);
    }).catch(() => {});
  }

  root.userData.handlers = {
    hover(active) {
      if (disposed) return;
      const entering = active !== false;
      gsap.killTweensOf(subject.position);
      gsap.to(subject.position, {
        y: entering ? 0 : -0.15,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    click() {
      if (!disposed) ctx.emit('hub-collection.select', { node: root });
    }
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const result of primitiveResults) {
      if (typeof result.cleanup === 'function') result.cleanup();
      if (result.timeline?.kill) result.timeline.kill();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) {
          if (entry?.dispose) entry.dispose();
        }
      } else if (material?.dispose) {
        material.dispose();
      }
    });

    root.clear();
  };

  return root;
}
